<body>
    <h1>Pendulum Simulator</h1>
    <input type="number" id="initial-angle" value="45" /> degrees
    <button id="release-button">Release</button>
    <canvas id="pendulumCanvas" width="400" height="400"></canvas>

    <script>
        let canvas = document.getElementById('pendulumCanvas');
        let ctx = canvas.getContext('2d');
        let width = canvas.width;
        let height = canvas.height;
        let amplitude = 0;
        let gravity = 0.1;
        let momentOfInertia = 0.1;
        let duration = 0;
        let isReleased = false;

        function drawPendulum() {
            ctx.clearRect(0, 0, width, height);
            ctx.fillStyle = 'rgba(0, 0, 0, 0.1)';
            ctx.fillRect(width / 2, height / 2, 10, 10); // pendulum bob
            ctx.strokeStyle = 'black';
            ctx.lineWidth = 2;
            ctx.beginPath();
            ctx.arc(width / 2, height / 2, 20, 0, Math.PI * 2);
            ctx.stroke();
            ctx.beginPath();
            ctx.arc(width / 2 + Math.cos(Math.PI / 2 + amplitude) * 20, height / 2 - Math.sin(Math.PI / 2 + amplitude) * 20, 10, 0, Math.PI * 2);
            ctx.fillStyle = 'black';
            ctx.fill();
        }

        function updatePendulum() {
            if (isReleased) {
                duration += 0.01;
                amplitude = Math.asin(Math.sin(duration * Math.sqrt(gravity / momentOfInertia)));
                if (Math.abs(amplitude) > Math.PI / 2) {
                    amplitude = -amplitude;
                }
                drawPendulum();
                requestAnimationFrame(updatePendulum);
            }
        }

        document.getElementById('release-button').addEventListener('click', function() {
            isReleased = true;
            amplitude = Math.PI / 180 * parseInt(document.getElementById('initial-angle').value);
            updatePendulum();
        });
    </script>
</body>
</html>
```

